/**
 * The AST and rule types devkit vendors stay exactly what the pinned
 * `@typescript-eslint/*` packages declare. A hand edit, or a parser upgrade
 * the snapshot was not regenerated for, fails here rather than shipping
 * types that disagree with the parser consumers run.
 *
 * docs/intents/2026-11-03-our-code-owns-the-tree (phase 1.1)
 */

import { describe, it, expect } from 'vitest';
import { spawnSync } from 'node:child_process';
import { resolve } from 'node:path';

const ROOT = resolve(__dirname, '..', '..');

describe('vendored estree types', () => {
  it('match the pinned @typescript-eslint packages byte for byte', () => {
    const check = spawnSync(
      'npx',
      ['tsx', 'scripts/vendor-estree-types.ts', '--check'],
      { cwd: ROOT, encoding: 'utf8' },
    );
    expect(check.status, `${check.stdout}${check.stderr}`).toBe(0);
  }, 120_000);
});
